insert into projects (id,name,client,year,summary,challenge,solution,final_thoughts,url,thumbnail,images,tags,categories,featured_color,featured_order,sort) values ('archline','Archline','Maisonluxe',2025,'Archline is a refined website for an architecture studio, designed to present projects with clarity, calm spacing, and a minimalist, elegant visual language.','The studio needed a digital presence that felt premium and architectural, while keeping navigation simple and allowing projects to remain the primary focus.','We structured the website with clean grids, generous whitespace, and restrained typography to create a calm browsing experience that highlights architecture.','Archline captures the studio’s philosophy through simplicity and precision, transforming the portfolio into a quiet, elegant experience that reflects architectural thinking.','','https://framerusercontent.com/images/EpE3EXTbHQgZGhvDOnYoCiOPO4Q.jpg',array['https://framerusercontent.com/images/EymozPaAATTf6rydKIrqAIptRsU.jpg','https://framerusercontent.com/images/FQo8E0jYggHvidGdQnZnNkIeIms.jpg','https://framerusercontent.com/images/IMUNWYEfkn5T37D2j6dPFh4kYBo.jpg','https://framerusercontent.com/images/9uBDaRfp8jzIPpGe9xupADgkI.jpg']::text[],array['Web Design','Framer Development']::text[],array['website']::text[],'#ff5f57',0,0);
insert into projects (id,name,client,year,summary,challenge,solution,final_thoughts,url,thumbnail,images,tags,categories,featured_color,featured_order,sort) values ('dewi','Dewi','Alex Luu',2025,'Dewi is a serene resort website inspired by Bali’s natural beauty, blending warm imagery, soft typography, and spacious layouts to evoke relaxation.','The resort needed a website that conveyed tranquility and luxury while clearly presenting accommodations, experiences, and booking information without overwhelming visitors.','We designed airy layouts with natural colors, immersive imagery, and gentle scrolling transitions to create a calm digital journey reflecting the resort atmosphere.','Dewi captures the spirit of a Bali getaway, transforming the website into a peaceful digital escape that invites visitors to relax and imagine their stay.','','https://framerusercontent.com/images/MZaxJjFtRo4mSnx24EjY6XllOg.png',array['https://framerusercontent.com/images/lIte5WocdwZOBvMNrXRz6OdTos.png','https://framerusercontent.com/images/u1FcPcPkmbTEkoXXiGYzyNCmPlU.jpg','https://framerusercontent.com/images/tP36bF9dCnTuEzzQ2OJ66pAFwtE.jpg','https://framerusercontent.com/images/rtmhvemWx36r95T3imM5QZfQ.jpg','https://framerusercontent.com/images/kWJhJ7MBBejIH1wBhGGONDPw2o.jpg']::text[],array['Brand Identity','Web Design']::text[],array['website']::text[],null,null,1);
insert into projects (id,name,client,year,summary,challenge,solution,final_thoughts,url,thumbnail,images,tags,categories,featured_color,featured_order,sort) values ('nonsence','Nonsence','Jamie',2024,'Nonsence is a minimal personal portfolio focused on typography, using clean layouts and restrained visuals to highlight projects with clarity and intention.','The challenge was creating a distinctive portfolio without relying on heavy visuals, allowing typography and spacing to carry personality and structure.','We built a simple grid, bold typographic hierarchy, and generous whitespace to guide attention, letting projects stand out without unnecessary decoration.','Nonsence demonstrates how minimal design and strong typography can create a confident portfolio that feels refined, focused, and timeless.','','https://framerusercontent.com/images/UJRysqwXqt9PEy3vxbN9XI5QXQ.png',array['https://framerusercontent.com/images/BoGTMK7AaJPSwR19PrCWBEkIdU.jpeg','https://framerusercontent.com/images/jR5nT4eidqPyGLPnkKhYwXBWTw.png','https://framerusercontent.com/images/pXMCuNOhpqCYOzFtPKZBZcq86A.png']::text[],array['Web Design','Motion Graphics']::text[],array['website']::text[],null,null,2);
insert into projects (id,name,client,year,summary,challenge,solution,final_thoughts,url,thumbnail,images,tags,categories,featured_color,featured_order,sort) values ('creatory','Creatory','Wilson',2023,'Creatory is a bold website for a Gen Z–focused social media agency, combining playful layouts, vibrant colors, and expressive typography.','The agency needed a website that felt energetic and culturally relevant while clearly presenting services, case studies, and credibility to potential clients.','We designed dynamic layouts with vibrant gradients, playful typography, and engaging micro-interactions to create an experience aligned with fast-moving social culture.','Creatory turns the agency’s identity into a lively digital presence that resonates with Gen Z audiences while maintaining clarity and strong brand personality.','','https://framerusercontent.com/images/BioZIG0GuLlZAIoshbFOCdctS7I.png',array['https://framerusercontent.com/images/uqKjhjevbBLdejvNTpHOHdjRe8.png','https://framerusercontent.com/images/RwJfvfA9ufwf6M2MM1DBM3p0UU.png','https://framerusercontent.com/images/nmExbQeqjxRG57npvnCrrvhhfrI.jpg','https://framerusercontent.com/images/CtDtwTfs20B0ZoX4YfKIx5DeTI.png']::text[],array['Web Design','Motion Graphics','3D Design']::text[],array['website']::text[],null,null,3);
insert into projects (id,name,client,year,summary,challenge,solution,final_thoughts,url,thumbnail,images,tags,categories,featured_color,featured_order,sort) values ('nexmind','Nexmind®','Simon Hale',2025,'Nexmind is a dark-mode website for an AI agency, combining futuristic visuals and structured layouts to present advanced technology in a clear, compelling way.','The agency needed a modern website that communicated complex AI capabilities while maintaining clarity, credibility, and a visually striking technological identity.','We designed a dark interface with glowing accents, modular sections, and bold typography to showcase services, simplify navigation, and emphasize innovation.','Nexmind transforms the agency’s presence into a confident digital platform that reflects technological depth while guiding visitors smoothly toward trust and engagement.','','https://framerusercontent.com/images/EPRSL4XDvXGg2KRgMLqqktSo.png',array['https://framerusercontent.com/images/N2RS74zXn9pmJpNEkbzk3HysSU.jpg','https://framerusercontent.com/images/GCipfAigW5tdV27gbBuLhY2B9fk.png','https://framerusercontent.com/images/Q9VWtO4xfyjoc8cc16ZRfTTzJk.jpg','https://framerusercontent.com/images/OsGx3Pbiv9v4DdmU5YTBQjNLdg.png']::text[],array['Brand Identity','Motion Graphics','3D Design']::text[],array['saas']::text[],'#febc2e',1,4);
insert into projects (id,name,client,year,summary,challenge,solution,final_thoughts,url,thumbnail,images,tags,categories,featured_color,featured_order,sort) values ('glaze','Glaze','Capi Agency',2026,'Glaze is a modern website for an AI agent platform, combining sleek visuals, structured layouts, and subtle motion to communicate intelligence and automation.','The challenge was presenting complex AI capabilities in a way that feels approachable, credible, and easy for visitors to understand quickly.','We designed modular sections, futuristic accents, and concise messaging to simplify product explanations while highlighting automation features and intelligent workflows.','Glaze positions the AI agent as a powerful yet accessible tool, transforming complex technology into a clear, engaging digital experience.','','https://framerusercontent.com/images/adZOUatDWxd54qP773wJrAePo.jpg',array['https://framerusercontent.com/images/ot3280OOVp3x550UVevzU70I.png','https://framerusercontent.com/images/G0cUgOPzBFAmQ6OoZuDfxuUSvmw.jpg','https://framerusercontent.com/images/TXb6XY1jscgFBvhuTnhJGTVEKXc.jpeg']::text[],array['Motion Graphics','3D Design']::text[],array['saas']::text[],'#28c840',2,5);
insert into projects (id,name,client,year,summary,challenge,solution,final_thoughts,url,thumbnail,images,tags,categories,featured_color,featured_order,sort) values ('brnd','BRND™','Jacob Olenick',2024,'BRND™ is a clean, minimal website designed to present brand guidelines clearly, helping teams and partners access essential assets and visual standards.','The challenge was organizing complex brand rules and assets into a simple structure that remains accessible, consistent, and easy to navigate.','We designed a structured layout with clear sections, restrained typography, and generous spacing to present brand elements in a calm, organized way.','BRND™ transforms brand documentation into a streamlined digital system, making guidelines easier to understand, share, and maintain across teams.','','https://framerusercontent.com/images/r8zjZl4nPR79RdtcO521JQC2iw.png',array['https://framerusercontent.com/images/vNCmGscmP8AZWPigQbWyz1UL4Hw.jpg','https://framerusercontent.com/images/VFeozosSzLUoaMd4cqV75XTjjCM.jpg','https://framerusercontent.com/images/dkLGf25J6u0rMKWEcoapWyfA4WQ.jpg','https://framerusercontent.com/images/1QbPIA8skAdl1OpVyHFL4xhiY8w.jpg']::text[],array['Web Design','Framer Development','Motion Graphics']::text[],array['development']::text[],null,null,6);
insert into settings (key,value) values ('about','{"name": "David Tran", "role": "Senior Product Designer · eUp Group", "avatar": "assets/framerusercontent.com/images/GDtwfDWvA44HAxAwR3Zp0UYLnRU.0vek3j5.png", "paragraphs": ["Hi there, my name is Tuan Anh aka David Tran", "I’m a Senior Product Designer at eUP Group, focused on crafting thoughtful and user-centered digital experiences. I work across product strategy, UX, and visual design to turn complex ideas into clear, usable products. My goal is to create designs that not only look great but also solve real problems and deliver meaningful value to users.", "I design interfaces that truly serve people. Ensuring they’re not just visually appealing but also intuitive and purposeful. Whether it’s a product dashboard, an app, or a portfolio, my aim is to craft experiences that feel natural and effortless.", "Details matter most to me. I believe precision is what elevates good design into great design. My eye for detail helps build trust with clients, because they know I’ll pour the same dedication into their projects as if they were my own."]}'::jsonb);
